import { notFound } from 'next/navigation'
import { getProduct, getRelatedProducts } from '@/lib/products'

export default async function ProductPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string }>
}) {
  const { slug } = await params
  const { currency = 'USD' } = await searchParams
  const product = await getProduct(slug, currency)
  if (!product) notFound()
  const related = await getRelatedProducts(slug)

  return (
    <main>
      <p>Signal Shop collection</p>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
      <section>
        <h2>Related products</h2>
        {related.map((item) => (
          <p key={item.slug}>{item.name}</p>
        ))}
      </section>
    </main>
  )
}
const products = {
  lamp: { slug: 'lamp', name: 'Brass lamp', usd: 120 },
  vase: { slug: 'vase', name: 'Stone vase', usd: 80 },
}

export async function getProduct(slug: string, currency: string) {
  await new Promise((resolve) => setTimeout(resolve, 120))
  const product = products[slug as keyof typeof products]
  if (!product) return null
  const rate = currency === 'EUR' ? 0.92 : 1
  return { ...product, price: `${currency} ${(product.usd * rate).toFixed(2)}` }
}

export async function getRelatedProducts(slug: string) {
  await new Promise((resolve) => setTimeout(resolve, 420))
  return Object.values(products).filter((product) => product.slug !== slug)
}

### Nested boundaries for progressive detail

You can nest `<Suspense>` boundaries to create a layered loading experience. For example, a product page might stream the header immediately, the product details next, and the reviews last:

```tsx filename="app/product/[id]/page.tsx" switcher
import { Suspense } from 'react'
import { ProductDetails } from './product-details'
import { Reviews } from './reviews'

export async function generateStaticParams() {
  const products = await getTopProducts()
  return products.map((product) => ({ id: product.id }))
}

export default async function ProductPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params

  return (
    <div>
      <h1>Product</h1>
      <Suspense fallback={<p>Loading product details...</p>}>
        <ProductDetails id={id} />
        <Suspense fallback={<p>Loading reviews...</p>}>
          <Reviews productId={id} />
        </Suspense>
      </Suspense>
    </div>
  )
}
```

```jsx filename="app/product/[id]/page.js" switcher
import { Suspense } from 'react'
import { ProductDetails } from './product-details'
import { Reviews } from './reviews'

export async function generateStaticParams() {
  const products = await getTopProducts()
  return products.map((product) => ({ id: product.id }))
}

export default async function ProductPage({ params }) {
  const { id } = await params

  return (
    <div>
      <h1>Product</h1>
      <Suspense fallback={<p>Loading product details...</p>}>
        <ProductDetails id={id} />
        <Suspense fallback={<p>Loading reviews...</p>}>
          <Reviews productId={id} />
        </Suspense>
      </Suspense>
